import{_ as s,o as n,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"26. 内存泄漏和未定义的行为","description":"The Little Book of C 中文版 — 26. 内存泄漏和未定义的行为","frontmatter":{"title":"26. 内存泄漏和未定义的行为","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","03-内存","中文"],"description":"The Little Book of C 中文版 — 26. 内存泄漏和未定义的行为","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":26,"sidebarWeight":26,"alternateZh":"/posts/c教程/zh-CN/03-内存/026-Memory Leaks and Undefined Behavior","alternateEn":"/posts/c教程/en-US/03-Working with Memory/026-Memory Leaks and Undefined Behavior"},"headers":[],"relativePath":"posts/c教程/zh-CN/03-内存/026-Memory Leaks and Undefined Behavior.md","filePath":"posts/c教程/zh-CN/03-内存/026-Memory Leaks and Undefined Behavior.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/03-内存/026-Memory Leaks and Undefined Behavior.md"};function p(l,a,o,d,c,r){return n(),e("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/03-Working with Memory/026-Memory Leaks and Undefined Behavior)</p><p>C 使您可以完全控制内存，这意味着您可以做任何您想做的事情，包括永远不应该做的事情。两个最大的危险是内存泄漏（当内存永远不会被释放时）和未定义的行为（当程序执行不可预测的操作时）。学会避免这些是编写稳定、安全和正确的 C 程序的关键。</p><h4 id="什么是内存泄漏" tabindex="-1">什么是内存泄漏？ <a class="header-anchor" href="#什么是内存泄漏" aria-label="Permalink to &quot;什么是内存泄漏？&quot;">​</a></h4><p>当您在堆上分配内存并且从未释放它时，就会发生内存泄漏。即使您无法再访问它，内存仍会保留。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>void leak(void) {</span></span>
<span class="line"><span>    int *data = malloc(100 * sizeof(int)); // allocated</span></span>
<span class="line"><span>    data[0] = 42;</span></span>
<span class="line"><span>    // forgot to free(data); memory is now lost</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果<code>leak()</code>运行多次后，您的程序会消耗越来越多的内存，直到崩溃或变慢。在长时间运行的程序（如服务器）中，这是致命的。</p><p>规则：每个<code>malloc</code>,<code>calloc</code>， 或者<code>realloc</code>最终必须与匹配的配对<code>free()</code>.</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>让我们看看泄漏和修复的实际情况。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>void with_leak(void) {</span></span>
<span class="line"><span>    int *arr = malloc(5 * sizeof(int));</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 5; i++) arr[i] = i;</span></span>
<span class="line"><span>    printf(&quot;with_leak: allocated 5 ints, but not freed.\\n&quot;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void without_leak(void) {</span></span>
<span class="line"><span>    int *arr = malloc(5 * sizeof(int));</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 5; i++) arr[i] = i;</span></span>
<span class="line"><span>    printf(&quot;without_leak: freeing memory.\\n&quot;);</span></span>
<span class="line"><span>    free(arr);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    with_leak();</span></span>
<span class="line"><span>    without_leak();</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>使用 Valgrind（内存检查器）编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc leaks_demo.c -o leaks_demo</span></span>
<span class="line"><span>valgrind ./leaks_demo</span></span></code></pre></div><p>Valgrind 输出（简化）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==1234== HEAP SUMMARY:</span></span>
<span class="line"><span>==1234==    definitely lost: 20 bytes in 1 blocks</span></span>
<span class="line"><span>==1234==    indirectly lost: 0 bytes in 0 blocks</span></span>
<span class="line"><span>==1234== LEAK SUMMARY:</span></span>
<span class="line"><span>==1234==    1 blocks definitely lost</span></span></code></pre></div><p>您可以看到第一个函数泄漏了内存，而第二个函数则正确释放了内存。</p><h4 id="悬空指针" tabindex="-1">悬空指针 <a class="header-anchor" href="#悬空指针" aria-label="Permalink to &quot;悬空指针&quot;">​</a></h4><p>悬空指针指向已释放或无效的内存。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *p = malloc(sizeof(int));</span></span>
<span class="line"><span>*p = 10;</span></span>
<span class="line"><span>free(p);</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, *p); // ❌ undefined behavior</span></span></code></pre></div><p>后<code>free(p)</code>, 指针<code>p</code>仍然保留旧地址，但该内存不再属于您。访问它可能会崩溃，或者看起来可以工作，或者损坏数据，你不能依赖它。</p><p>始终使释放的指针无效：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>free(p);</span></span>
<span class="line"><span>p = NULL;</span></span></code></pre></div><h4 id="双重免费" tabindex="-1">双重免费 <a class="header-anchor" href="#双重免费" aria-label="Permalink to &quot;双重免费&quot;">​</a></h4><p>两次释放相同的内存也会导致未定义的行为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *p = malloc(sizeof(int));</span></span>
<span class="line"><span>free(p);</span></span>
<span class="line"><span>free(p); // ❌ double free error</span></span></code></pre></div><p>大多数现代操作系统都会检测到这一点并中止，但这仍然是一个严重的错误。</p><h4 id="释放后使用" tabindex="-1">释放后使用 <a class="header-anchor" href="#释放后使用" aria-label="Permalink to &quot;释放后使用&quot;">​</a></h4><p>这是最严重的内存错误之一。当您在释放内存后访问内存时，就会发生这种情况。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *arr = malloc(3 * sizeof(int));</span></span>
<span class="line"><span>arr[0] = 5;</span></span>
<span class="line"><span>free(arr);</span></span>
<span class="line"><span>arr[0] = 7; // ❌ use-after-free</span></span></code></pre></div><p>编译器不会发现这一点，但 Valgrind 会警告你。</p><h4 id="未初始化内存" tabindex="-1">未初始化内存 <a class="header-anchor" href="#未初始化内存" aria-label="Permalink to &quot;未初始化内存&quot;">​</a></h4><p>读取从未写入过的内存也是未定义的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *arr = malloc(5 * sizeof(int));</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, arr[2]); // ❌ uninitialized read</span></span></code></pre></div><p><code>malloc()</code>不将内存清零，使用<code>calloc()</code>如果您需要清除数据。</p><h4 id="未定义行为的常见原因" tabindex="-1">未定义行为的常见原因 <a class="header-anchor" href="#未定义行为的常见原因" aria-label="Permalink to &quot;未定义行为的常见原因&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>示例</th><th>后果</th></tr></thead><tbody><tr><td>越界访问</td><td><code>arr[10]</code>在 5 元素数组中</td><td>破坏记忆</td></tr><tr><td>免费后使用</td><td>取消引用已释放的指针</td><td>崩溃还是无声的腐败</td></tr><tr><td>空指针取消引用</td><td><code>*NULL</code></td><td>崩溃</td></tr><tr><td>除以零</td><td><code>x / 0</code></td><td>崩溃</td></tr><tr><td>无效的指针算术</td><td><code>(int *)0 + 1</code></td><td>未定义</td></tr><tr><td>修改字符串文字</td><td><code>char *s = &quot;hi&quot;; s[0]=&#39;H&#39;;</code></td><td>崩溃</td></tr></tbody></table><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>未定义的行为不仅仅是“一个错误”。这意味着任何事情都可能发生：</p><ul><li>你的程序可能看起来不错，但后来会失败。</li><li>编译器优化可能会意外删除或重新排序代码。</li><li>相同的代码可能在一个系统上运行，但在另一个系统上崩溃。</li></ul><p>在 C 语言中，正确性是你的责任。您必须知道内存何时有效、谁拥有它以及何时释放它。</p><h4 id="防御技术" tabindex="-1">防御技术 <a class="header-anchor" href="#防御技术" aria-label="Permalink to &quot;防御技术&quot;">​</a></h4><ol><li>经常检查<code>malloc()</code>返回值。</li><li>初始化指针<code>NULL</code>.</li><li>将指针设置为<code>NULL</code>释放后。</li><li>使用 Valgrind (Linux) 或 AddressSanitizer (Clang/GCC) 检测泄漏和无效访问。</li><li>喜欢小型、可测试的函数，更容易验证内存所有权。</li><li>避免混合堆栈和堆内存，除非您确定生命周期。</li></ol><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个故意泄漏内存的小程序。在 Valgrind 下运行它。 2.通过调用修复泄漏<code>free()</code>适当地。</li><li>创建一个悬空指针并观察会发生什么（在某些系统上它会崩溃，在其他系统上则不会）。</li><li>尝试<code>calloc()</code>查看零初始化内存的行为方式。</li><li>编写一个分配内存并返回内存的函数，然后确保调用者释放它。</li></ol><h4 id="最后的想法" tabindex="-1">最后的想法 <a class="header-anchor" href="#最后的想法" aria-label="Permalink to &quot;最后的想法&quot;">​</a></h4><p>内存错误是最难跟踪的错误，因为它们可能不会立即出现。但是一旦你了解了所有权、谁分配、谁释放，C 语言中的内存就变得可预测，甚至是优雅的。这种纪律是将临时 C 用户与真正的系统程序员区分开来的。</p>`,46)])])}const b=s(i,[["render",p]]);export{u as __pageData,b as default};
